cat > zz_heldout_test.go <<'EOF'
package shop

import "testing"

func TestHeldoutApplyCouponClamps(t *testing.T) {
	for _, c := range []struct{ total, percent, want int }{
		{1000, 15, 850},
		{1000, 0, 1000},
		{1000, 100, 0},
		{1000, 150, 0},
		{1000, -20, 1000},
	} {
		if got := ApplyCoupon(c.total, c.percent); got != c.want {
			t.Errorf("ApplyCoupon(%d, %d) = %d, want %d", c.total, c.percent, got, c.want)
		}
	}
}
EOF
go test -count=1 -run Heldout ./...; rc=$?; rm -f zz_heldout_test.go; exit $rc

